mapper.select:
SELECT id, login_name, display_name, pin_hash, app_role, enabled, created_at, last_login_at
FROM app_users
WHERE id = #{userId}

mapper.update:
UPDATE app_users
SET last_login_at = #{lastLoginAt}
WHERE id = #{userId}

UPDATE app_users
SET app_role = #{appRole}
WHERE id = #{userId}
  AND enabled = TRUE

UPDATE app_users
SET pin_hash = #{pinHash}
WHERE id = #{userId}
  AND enabled = TRUE

UPDATE app_users
SET enabled = #{enabled}
WHERE id = #{userId}
